CW=`.kdw{display:flex;flex-wrap:wrap;gap:1rem;justify-content:center;align-items:flex-start;width:100%}
.kdw-sc{flex:0 1 auto;width:min(100%,31rem,calc((100dvh - 14rem)*.875));min-width:min(100%,17rem);aspect-ratio:350/400;border-radius:var(--ui-r-lg);overflow:hidden;border:1px solid var(--ui-border);box-shadow:var(--ui-shadow);background:#9FD3F5}
.kdw-sc>svg{display:block;width:100%;height:100%;touch-action:none}
.kdw-side{flex:1 1 17rem;max-width:31rem;display:flex;flex-direction:column;gap:.7rem}
.kdw-me{display:flex;flex-wrap:wrap;gap:.35rem;justify-content:center;align-items:center;padding:.35rem;border-radius:999px;background:var(--ui-surface);border:1px solid var(--ui-border)}
.kdw-sw,.kdw-hr{flex:none;width:2.55rem;height:2.55rem;padding:0;border-radius:50%;border:3px solid var(--ui-surface);box-shadow:0 0 0 2px var(--ui-border);cursor:pointer}
.kdw-hr{width:2.75rem;height:2.75rem;border:none;background:color-mix(in srgb,var(--lv) 18%,var(--ui-surface-2))}
.kdw-hr svg{width:100%;height:100%;border-radius:50%}
.kdw-sw.on,.kdw-hr.on{box-shadow:0 0 0 .22rem var(--lv)}
.kdw-sep{width:2px;height:2rem;background:var(--ui-border)}
.kdw-tray{display:grid;grid-template-columns:repeat(auto-fill,minmax(4.7rem,1fr));gap:.5rem;padding:.55rem;background:var(--ui-surface-2);border:1px solid var(--ui-border);border-radius:var(--ui-r-lg);min-height:5.5rem}
.kdw-it{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:.15rem;min-height:5.3rem;padding:.35rem .2rem;border-radius:var(--ui-r);background:color-mix(in srgb,var(--lv) 10%,var(--ui-surface));border:2px solid var(--ui-border);box-shadow:0 3px 0 var(--ui-border);cursor:grab;touch-action:none;box-sizing:border-box;color:var(--ui-text)}
.kdw-it svg{width:3.4rem;height:3.4rem;overflow:visible;pointer-events:none}
.kdw-it span{font:700 .78rem/1.1 var(--ui-round,var(--ui-sans));text-align:center}
.kdw-it:focus-visible{outline:.2rem solid var(--lv);outline-offset:.1rem}
.kdw-go{display:flex;align-items:center;justify-content:center;gap:.5rem;min-height:3.5rem;font-size:1.3rem;font-family:var(--ui-round,var(--ui-sans))}
.kdw-go svg{width:1.5rem;height:1.5rem}
.kdw-w{cursor:pointer;transform-box:fill-box;transform-origin:50% 50%}
.kdw-new{animation:kdw-pop .45s cubic-bezier(.3,1.5,.5,1)}
@keyframes kdw-pop{from{transform:scale(.7);opacity:0}}
.kdw-ok{filter:url(#kdw-g)}
.kdw-no{animation:kdw-wob .55s 2}
@keyframes kdw-wob{25%{transform:rotate(-7deg)}75%{transform:rotate(7deg)}}
.kdw-ms{fill:rgba(255,255,255,.3);stroke:#fff;stroke-width:3;stroke-dasharray:7 5;animation:kdw-pulse .9s ease-in-out infinite alternate;transform-box:fill-box;transform-origin:50% 50%}
@keyframes kdw-pulse{to{transform:scale(1.25);opacity:.55}}
.kdw-yay{animation:kdw-hop .55s ease-in-out 3}
@keyframes kdw-hop{45%{transform:translateY(-18px) rotate(-2deg)}55%{transform:translateY(-18px) rotate(2deg)}}
.kdw-rn{animation:kdw-rn .8s linear infinite}
@keyframes kdw-rn{from{transform:translate(20px,-210px)}to{transform:translate(-20px,210px)}}
.kdw-sn{animation:kdw-sn 7s linear infinite}
@keyframes kdw-sn{from{transform:translate(-10px,-210px)}50%{transform:translate(10px,0)}to{transform:translate(-10px,210px)}}
.kdw-lf{transform-box:fill-box;transform-origin:50% 50%;animation:kdw-lf 5s linear infinite}
@keyframes kdw-lf{from{transform:translate(-200px,-30px) rotate(0)}to{transform:translate(200px,40px) rotate(720deg)}}
.kdw-rays{transform-origin:54px 54px;animation:kdw-spin 30s linear infinite}
@keyframes kdw-spin{to{transform:rotate(1turn)}}
.kdw-cl{animation:kdw-drift 9s ease-in-out infinite alternate}
@keyframes kdw-drift{to{transform:translateX(15px)}}
.kdw-rip{transform-box:fill-box;transform-origin:50% 50%;animation:kdw-rip 1.8s ease-out infinite}
@keyframes kdw-rip{from{transform:scale(.3);opacity:.9}to{transform:scale(1.4);opacity:0}}
.kdw-gust{stroke-dasharray:40 300;animation:kdw-gust 3s linear infinite}
@keyframes kdw-gust{from{stroke-dashoffset:340}to{stroke-dashoffset:0}}
.kdw-fin{width:min(13rem,70vw);height:auto;display:block;margin:0 auto}
@media (prefers-reduced-motion:reduce){.kdw *,.kdw-fin,.kdw-fin *{animation:none!important}}
html.a11y-rm .kdw *,html.a11y-rm .kdw-fin,html.a11y-rm .kdw-fin *{animation:none!important}`;
